class InventoryTest(unittest.TestCase):
    def test_total_quantity(self):
        self.assertEqual(total_quantity(ITEMS), 34)

    def test_find(self):
        self.assertEqual(find(ITEMS, "nut")["quantity"], 4)
        self.assertIsNone(find(ITEMS, "gear"))

    def test_low_stock_sorts_names_and_excludes_threshold(self):
        items = [
            {"name": "zinc", "quantity": 11},
            {"name": "alpha", "quantity": 0},
            {"name": "at-threshold", "quantity": 12},
            {"name": "beta", "quantity": 3},
        ]
        self.assertEqual(low_stock(items), ["alpha", "beta", "zinc"])

    def test_low_stock_empty_for_no_items(self):
        self.assertEqual(low_stock([]), [])


if __name__ == "__main__":
    unittest.main()

